(1742083, 234632, 40977, '<td valign="top">Simple and creative.  Nicely done --8--</td>', 'Simple and creative.  Nicely done --8--', '2005-09-27 11:45:26.000000', NULL, 1),
(1742086, 234344, 40977, '<td valign="top">Lovely - A great shot.  Focus, color, composition is spot on. Brilliant job. --10--</td>', 'Lovely - A great shot.  Focus, color, composition is spot on. Brilliant job. --10--', '2005-09-27 11:46:14.000000', NULL, 1),
