(1742209, 233348, 38418, '<td valign="top">very nice lighting on the fur and focus on the eyes</td>', 'very nice lighting on the fur and focus on the eyes', '2005-09-27 12:57:53.000000', NULL, 1),
(1742210, 232645, 38418, '<td valign="top">nice lighting</td>', 'nice lighting', '2005-09-27 12:58:24.000000', NULL, 1),
(1742217, 234392, 38418, '<td valign="top">nice colors</td>', 'nice colors', '2005-09-27 13:02:10.000000', NULL, 1),
